const money=v=>new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR'}).format(v);let config={},size=null,items=[];const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;const scene=document.querySelector('#productScene'),visual=document.querySelector('#productVisual'),bag=document.querySelector('#bag');try{items=JSON.parse(localStorage.getItem('tensa-drop001-bag')||'[]').filter(x=>['XS','S','M','L','XL'].includes(x.size)&&Number.isInteger(x.qty)&&x.qty>0&&x.qty<=10)}catch{}
function save(){try{localStorage.setItem('tensa-drop001-bag',JSON.stringify(items))}catch{}document.querySelector('#cartCount').textContent=items.reduce((n,x)=>n+x.qty,0)}
function renderBag(){document.querySelector('#bagItems').innerHTML=items.length?items.map((x,i)=>`<div class="cart-line"><div>Washed Zip Hoodie<br><small>Washed Black / ${x.size}</small><div style="margin-top:12px"><button data-index="${i}" data-delta="-1" aria-label="Menge reduzieren">−</button> ${x.qty} <button data-index="${i}" data-delta="1" aria-label="Menge erhöhen">+</button> <button data-remove="${i}">Entfernen</button></div></div><span>${config.price?money(Number(config.price)*x.qty):'Preis folgt'}</span></div>`).join(''):'<p>Deine Bag ist noch leer.</p>';document.querySelector('#bagTotal').textContent=config.price?'Zwischensumme: '+money(items.reduce((n,x)=>n+x.qty*Number(config.price),0)):'Der finale Preis folgt.'}
document.querySelectorAll('[data-size]').forEach(b=>b.onclick=()=>{size=b.dataset.size;document.querySelectorAll('[data-size]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelector('#productStatus').textContent='Größe '+size+' ausgewählt.'});document.querySelector('#addBag').onclick=()=>{if(!size){document.querySelector('#productStatus').textContent='Wähle zuerst deine Größe.';document.querySelector('[data-size]').focus();return}let item=items.find(x=>x.size===size);if(item)item.qty=Math.min(10,item.qty+1);else items.push({size,qty:1});save();renderBag();bag.showModal()};document.querySelector('#openCart').onclick=()=>{renderBag();bag.showModal()};document.querySelector('#closeCart').onclick=document.querySelector('#continueShopping').onclick=()=>bag.close();document.querySelector('#bagItems').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.remove!==undefined)items.splice(Number(b.dataset.remove),1);else{const i=Number(b.dataset.index);items[i].qty=Math.min(10,items[i].qty+Number(b.dataset.delta));if(items[i].qty<1)items.splice(i,1)}save();renderBag()};save();
let video=null,progress=0,queued=false;function updateScroll(){queued=false;const rect=scene.getBoundingClientRect();progress=reduce?0:Math.max(0,Math.min(1,-rect.top/(scene.offsetHeight-innerHeight)));const settle=Math.max(0,(progress-.65)/.35);visual.style.transform=`translateY(${-settle*innerHeight*.13}px) scale(${1-settle*.32})`;document.querySelector('#scrollProgress').style.height=progress*100+'%';document.querySelector('#viewLabel').textContent=progress<.45?'01 / FRONT':progress<.75?'02 / TURN':'03 / BACK';if(video&&Number.isFinite(video.duration)&&video.readyState>=2&&!video.seeking){const target=Math.min(progress/.75,1)*Math.max(0,video.duration-.05);if(Math.abs(video.currentTime-target)>.04)video.currentTime=target}}
addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(updateScroll)}},{passive:true});addEventListener('resize',updateScroll);
fetch('/api/config').then(r=>r.json()).then(c=>{config=c;document.querySelector('#previewBanner').hidden=!c.admin||c.launched;document.querySelector('#price').textContent=c.price?money(Number(c.price)):'Preis folgt';if(c.film&&!reduce){video=document.createElement('video');video.src=c.film;video.muted=true;video.playsInline=true;video.preload='auto';video.setAttribute('aria-label','TENSA Zip-Hoodie dreht sich beim Scrollen von der Vorderseite zur Rückseite');if(c.productFront)video.poster=c.productFront;visual.replaceChildren(video);video.addEventListener('loadeddata',updateScroll);video.addEventListener('seeked',updateScroll)}else if(c.productFront){const img=new Image();img.src=c.productFront;img.alt='TENSA Zip-Hoodie, Vorderseite';visual.replaceChildren(img);if(reduce&&c.productBack){const back=new Image();back.src=c.productBack;back.alt='TENSA Zip-Hoodie, Rückseite mit Architekturprint';back.style.cssText='width:100%;max-height:480px;object-fit:contain';document.querySelector('.product-info>div').prepend(back)}}updateScroll()}).catch(()=>document.querySelector('#productStatus').textContent='Die Produktdaten sind gerade nicht erreichbar. Bitte lade die Seite erneut.');
